document.addEventListener('DOMContentLoaded',()=>{
const area=document.querySelector('[data-paper]');
if(area){const key='emotion-learning-v1',id=area.dataset.paper,note=document.querySelector('#deep-note'),read=document.querySelector('#deep-read'),out=document.querySelector('#note-status');
const get=()=>{try{const v=JSON.parse(localStorage.getItem(key)||'null');if(!v||typeof v!=='object')throw Error('invalid state');return {...v,weeks:Array.isArray(v.weeks)?v.weeks:[],papers:Array.isArray(v.papers)?v.papers.filter(x=>typeof x==='string'):[],notes:v.notes&&typeof v.notes==='object'&&!Array.isArray(v.notes)?v.notes:{},quizBest:Number(v.quizBest)||0};}catch(e){return {weeks:[],papers:[],notes:{},quizBest:0};}};
let state=get();const shared=location.hostname==='0912904.github.io'&&location.pathname.startsWith('/emotion-learning/');note.value=state.notes?.[id]||'';read.checked=(state.papers||[]).includes(id);if(shared){read.disabled=true;read.parentElement.append('（共享阅读状态请在阅读室管理）');}out.setAttribute('role','status');out.setAttribute('aria-live','polite');
try{state.lastVisited={type:'paper',id};state.inProgress=Array.isArray(state.inProgress)?state.inProgress:[];if(!shared&&!read.checked&&!state.inProgress.includes(id))state.inProgress.push(id);localStorage.setItem(key,JSON.stringify(state));}catch{out.textContent='无法保存阅读位置，请导出或复制笔记备份';}
let timer;
const save=()=>{clearTimeout(timer);timer=null;try{let s=get();s.notes=s.notes||{};s.notes[id]=note.value.slice(0,20000);if(!shared){s.papers=(s.papers||[]).filter(x=>x!==id);s.inProgress=(Array.isArray(s.inProgress)?s.inProgress:[]).filter(x=>x!==id);if(read.checked)s.papers.push(id);else s.inProgress.push(id);}s.updatedAt=new Date().toISOString();localStorage.setItem(key,JSON.stringify(s));out.textContent='已保存 · 刚刚';}catch(e){out.textContent='保存失败，请复制笔记备份';}};
note.addEventListener('input',()=>{clearTimeout(timer);out.textContent='正在保存…';timer=setTimeout(save,300);});read.addEventListener('change',save);addEventListener('pagehide',()=>{if(timer)save();});
addEventListener('storage',e=>{if(e.key!==key||document.activeElement===note)return;const s=get();note.value=s.notes[id]||'';read.checked=s.papers.includes(id);});}
const search=document.querySelector('#collection-search'),filter=document.querySelector('#collection-filter');if(search){const update=()=>{let n=0;document.querySelectorAll('.collection-card').forEach(c=>{const ok=c.textContent.toLowerCase().includes(search.value.toLowerCase())&&(filter.value==='all'||c.dataset.group===filter.value);c.hidden=!ok;if(ok)n++;});document.querySelector('#collection-count').textContent=`显示 ${n} 篇`};search.addEventListener('input',update);filter.addEventListener('change',update);update();}
});
